<?php
require_once __DIR__.'/includes/bootstrap.php';require_auth();$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT o.*,o.reference AS code,o.date_promise AS date_prevue,o.depose_par AS user_id,c.nom,c.prenom,c.telephone FROM commandes o JOIN clients c ON c.id=o.client_id WHERE o.id=?");$s->execute([$id]);$o=$s->fetch();if(!$o)exit('Introuvable');$s=db()->prepare("SELECT l.*,l.sous_total AS subtotal FROM commande_lignes l WHERE l.commande_id=?");$s->execute([$id]);$items=$s->fetchAll();$s=db()->prepare("SELECT * FROM paiements WHERE commande_id=?");$s->execute([$id]);$payments=$s->fetchAll();?><!doctype html><html lang="fr"><meta charset="utf-8"><title>Reçu <?=e($o['code'])?></title><style>body{font:14px Arial;max-width:800px;margin:35px auto;color:#172554}h1{color:#3157d5}table{width:100%;border-collapse:collapse;margin:20px 0}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}.right{text-align:right}.print{background:#3157d5;color:white;border:0;padding:10px 18px;border-radius:6px}@media print{.print{display:none}}</style><h1>✦ Pressa</h1><p>Reçu / Bon de dépôt</p><hr><h2><?=e($o['code'])?></h2><p>Client : <?=e($o['prenom'].' '.$o['nom'])?> · <?=e($o['telephone'])?><br>Dépôt : <?=e($o['type_depot'])?> · Date : <?=date('d/m/Y',strtotime($o['date_depot']))?><br>Retrait prévu : <?=e($o['date_prevue'])?></p><table><tr><th>Prestation / vêtement</th><th>Qté</th><th>PU</th><th>Total</th></tr><?php foreach($items as $it):?><tr><td><?=e($it['description'])?></td><td><?=$it['quantite']?></td><td><?=money($it['prix_unitaire'])?></td><td><?=money($it['subtotal'])?></td></tr><?php endforeach;?></table><?php if(!empty($o['surcharge_express'])):?><p class="right">Majoration express : <?=money($o['surcharge_express'])?></p><?php endif;?><h3 class="right">Total : <?=money($o['total'])?></h3><p>Merci de votre confiance.</p><button class="print" onclick="window.print()">Imprimer</button></html>
